#!/bin/bash
# Uninstall script for Atlassian SourceTree
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Atlassian SourceTree..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Atlassian SourceTree if running..."
pkill -f "Atlassian SourceTree" 2>/dev/null || true

